{
  "type": "Catalog",
  "id": "trazofields",
  "stac_version": "1.1.0",
  "description": "10.9 million agricultural field boundaries across South America for the 2023–2024 planting season, delineated from Sentinel-2 imagery by the Trazo model suite (U-Net / EfficientNet-B3, built on Fields of The World). Published as three collections, one per model — trazo3-fields is recommended for most use cases. Intended to support supply chain traceability, EUDR compliance workflows, and field-level deforestation monitoring.",
  "links": [
    {
      "rel": "root",
      "href": "./catalog.json",
      "type": "application/json",
      "title": "Trazo Fields"
    },
    {
      "rel": "child",
      "href": "./trazo1-fields/collection.json",
      "title": "Trazo1 Field Boundaries — Brazil (2023–2024)"
    },
    {
      "rel": "child",
      "href": "./trazo2-fields/collection.json",
      "title": "Trazo2 Field Boundaries — Brazil & Paraguay (2023–2024)"
    },
    {
      "rel": "child",
      "href": "./trazo3-fields/collection.json",
      "title": "Trazo3 Field Boundaries — South America (2023–2024)"
    },
    {
      "rel": "child",
      "href": "./eap-release/catalog.json",
      "type": "application/json",
      "title": "Trazo Field Boundaries — Early Adopters Program Release (2025)"
    },
    {
      "rel": "via",
      "href": "https://www.wri.org/research/field-boundaries-south-america",
      "type": "text/html",
      "title": "Trazo technical note (Grupp et al. 2026)"
    },
    {
      "rel": "llms",
      "href": "./llms.txt",
      "type": "text/plain",
      "title": "LLM-oriented catalog summary"
    }
  ],
  "title": "Trazo Field Boundaries of South America"
}

