input.content:
LOAD spatial;

CREATE TEMP TABLE buffered_union AS
SELECT ST_Union_Agg(ST_Buffer(geometry, 25.0/111320.0)) AS geom FROM car_matches;

DROP TABLE IF EXISTS field_single;
CREATE TABLE field_single AS
SELECT f.Id AS field_id, c.cod_imovel,
       ST_Area(ST_Intersection(f.geometry, c.geometry)) AS inter_area,
       ST_Area(f.geometry) AS field_area
FROM fields_env f
JOIN car_matches c ON ST_Intersects(f.geometry, c.geometry);

DROP TABLE IF EXISTS field_best_single;
CREATE TABLE field_best_single AS
SELECT field_id, cod_imovel AS best_cod_imovel, field_area,
       inter_area / field_area AS max_single_frac
FROM (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY field_id ORDER BY inter_area/field_area DESC, cod_imovel ASC) rn
  FROM field_single
) WHERE rn = 1;

DROP TABLE IF EXISTS field_agg;
CREATE TABLE field_agg AS
SELECT f.Id AS field_id,
       ST_Area(f.geometry) AS field_area,
       ST_Area(ST_Intersection(f.geometry, u.geom)) / ST_Area(f.geometry) AS union_frac
FROM fields_env f, buffered_union u
WHERE ST_Intersects(f.geometry, u.geom);

DROP TABLE IF EXISTS field_match;
CREATE TABLE field_match AS
SELECT
  coalesce(bs.field_id, ag.field_id) AS field_id,
  bs.best_cod_imovel,
  coalesce(bs.max_single_frac, 0.0) AS max_single_frac,
  coalesce(ag.union_frac, 0.0) AS union_frac,
  (coalesce(bs.max_single_frac,0.0) >= 0.667) AS by_primary,
  (coalesce(ag.union_frac,0.0) >= 0.667) AS by_aggregate
FROM field_best_single bs
FULL OUTER JOIN field_agg ag ON bs.field_id = ag.field_id;

SELECT count(*) total_considered FROM field_match;
SELECT count(*) matched FROM field_match WHERE by_primary OR by_aggregate;

