"

duckdb eudr.duckdb -c "
LOAD spatial;
SELECT sum(ST_Area_Spheroid(f.geometry))/10000.0 AS matched_field_ha
FROM fields_env f
JOIN (SELECT DISTINCT field_id FROM field_match WHERE by_primary OR by_aggregate) m ON f.Id = m.field_id;
"

duckdb eudr.duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
SELECT sum(ST_Area_Spheroid(f.geometry))/10000.0 AS matched_field_ha
FROM fields_env f
JOIN (SELECT DISTINCT field_id FROM field_match WHERE by_primary OR by_aggregate) m ON f.Id = m.field_id;
"

duckdb eudr.duckdb -c "
LOAD spatial;
CREATE TEMP TABLE t AS SELECT * FROM fields_env LIMIT 1;
SELECT ST_AsText(geometry) FROM t;
SET geometry_always_xy=false;
SELECT ST_Area_Spheroid(geometry)/10000 AS ha_default FROM t;
SET geometry_always_xy=true;
SELECT ST_Area_Spheroid(geometry)/10000 AS ha_xy FROM t;
SELECT ST_Area(ST_Transform(geometry,'EPSG:4326','EPSG:5880',true))/10000 AS ha_5880 FROM t;
"

duckdb eudr.duckdb -c "
LOAD spatial;
CREATE TEMP TABLE t AS SELECT * FROM fields_env LIMIT 1;
SET geometry_always_xy=false;
SELECT ST_Area_Spheroid(geometry)/10000 AS ha_default FROM t;
SET geometry_always_xy=true;
SELECT ST_Area_Spheroid(geometry)/10000 AS ha_xy FROM t;
SELECT ST_Area(ST_Transform(geometry,'EPSG:4326','EPSG:5880',true))/10000 AS ha_5880 FROM t;
" 2>&1 | grep -v "^$"

duckdb eudr.duckdb -c "
DROP TABLE IF EXISTS flagged;
CREATE TABLE flagged AS
SELECT DISTINCT cod_imovel FROM matched_fields_full
WHERE mbmode24 IN (15,21,39) AND loss2124_ha > 0;
SELECT count(*) FROM flagged;
"

duckdb eudr.duckdb -c "
DROP TABLE IF EXISTS flagged_dominant;
CREATE TABLE flagged_dominant AS
WITH class_ha AS (
  SELECT cod_imovel, mbmode24, sum(field_area_ha) ha
  FROM matched_fields_full
  WHERE cod_imovel IN (SELECT cod_imovel FROM flagged)
  GROUP BY 1,2
),
ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY cod_imovel ORDER BY ha DESC, mbmode24 ASC) rn
  FROM class_ha
)
SELECT cod_imovel, mbmode24::int AS dominant_mb, ha FROM ranked WHERE rn=1;
SELECT * FROM flagged_dominant ORDER BY cod_imovel;
"

