duckdb eudr.duckdb -c "
LOAD spatial;
DROP TABLE IF EXISTS q26_result;
CREATE TABLE q26_result AS
WITH candidates AS (
  SELECT fc.cod_imovel, fc.dominant_mb, f.entity_id, f.tier,
         ST_Distance(fc.centroid_5880, f.geom_5880)/1000.0 AS distance_km
  FROM flagged_centroids fc
  JOIN facilities_5880 f
    ON (fc.dominant_mb IN (15,21) AND f.tier='slaughter_point')
    OR (fc.dominant_mb = 39 AND f.tier='intake_point' AND f.weight >= 1000)
),
ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY cod_imovel ORDER BY distance_km ASC, entity_id ASC) rn
  FROM candidates
)
SELECT cod_imovel, entity_id, tier, distance_km FROM ranked WHERE rn=1;
SELECT * FROM q26_result ORDER BY cod_imovel;
"

