LOAD spatial; LOAD httpfs;
SET geometry_always_xy=true;

-- all delivery candidates (intake+slaughter+mill) within 300km ceiling for each flagged cadaster,
-- restricted to the tier(s) its commodity routes to
DROP TABLE IF EXISTS all_facilities_5880;
CREATE TABLE all_facilities_5880 AS
SELECT entity_id, entity_kind, tier, weight, basis, geom_method, source,
       ST_Transform(geometry, 'EPSG:4326','EPSG:5880', true) AS geom_5880
FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet')
WHERE tier IN ('intake_point','slaughter_point','mill_point','gravity_catchment');

DROP TABLE IF EXISTS delivery_candidates;
CREATE TABLE delivery_candidates AS
WITH routed AS (
  SELECT cod_imovel, dominant_mb, centroid_5880,
    CASE dominant_mb WHEN 15 THEN ['slaughter_point'] WHEN 21 THEN ['slaughter_point']
                      WHEN 39 THEN ['intake_point'] END AS point_tiers
  FROM flagged_centroids
)
SELECT r.cod_imovel, r.dominant_mb, f.entity_id, f.entity_kind, f.tier, f.basis,
       ST_Distance(r.centroid_5880, f.geom_5880)/1000.0 AS distance_km
FROM routed r
JOIN all_facilities_5880 f
  ON list_contains(r.point_tiers, f.tier)
  AND (f.tier != 'intake_point' OR f.weight >= 1000)
WHERE ST_Distance(r.centroid_5880, f.geom_5880)/1000.0 <= 300;

SELECT cod_imovel, tier, count(*) FROM delivery_candidates GROUP BY 1,2 ORDER BY 1,2;

